import app from 'flarum/common/app';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Tooltip from 'flarum/common/components/Tooltip';
import Avatar from 'flarum/common/components/Avatar';
import Link from 'flarum/common/components/Link';
import Widget from '../../../forum-widgets-core/common/components/Widget';
import onlineUsersState from '../onlineUsersState';
import { live, loadOnline, activityText, onlinePageUrl } from '../onlineLive';

/** Kartta en fazla bu kadar kişi; fazlası /cevrimici sayfasında */
const CARD_LIMIT = 4;

/**
 * Çevrimiçi kartı: istatistik kartıyla aynı tasarım dili. Kişi başına tek satır
 * (avatar · ad · ne yaptığı), ilk birkaç kişi; tamamı /cevrimici sayfasında.
 * Etkinliği görme izni olmayanlar yalnızca avatarları görür.
 */
export default class OnlineUsersWidget extends Widget {
  timer = null;
  className() {
    return 'FoF-OnlineUsersWidget Framio-OnlineWidget';
  }
  icon() {
    return 'fas fa-user-friends';
  }
  title() {
    const total = this.activityMode() ? live.total : app.forum.totalOnlineUsers() || 0;
    return 'Şu an çevrimiçi' + (total ? ` · ${total}` : '');
  }
  activityMode() {
    return !!app.forum.attribute('canViewUserActivity');
  }
  oncreate(vnode) {
    super.oncreate(vnode);
    if (!this.activityMode()) return;
    loadOnline(0);
    this.timer = window.setInterval(() => {
      if (document.visibilityState === 'visible') loadOnline(0, true);
    }, 30000);
  }
  onremove(vnode) {
    super.onremove(vnode);
    if (this.timer) window.clearInterval(this.timer);
  }
  content() {
    return this.activityMode() ? this.viewActivity() : this.viewAvatars();
  }
  avatar(r) {
    return r.avatarUrl ? m("img", {
      className: "Framio-Online-avatar",
      src: r.avatarUrl,
      alt: "",
      loading: "lazy"
    }) : m("span", {
      className: "Framio-Online-avatar is-letter"
    }, (r.displayName || '?').charAt(0).toLocaleUpperCase('tr-TR'));
  }
  viewActivity() {
    if (live.rows === null) return m(LoadingIndicator, null);
    const rows = live.rows;
    if (!rows.length) return m("div", {
      className: "Framio-Online-empty"
    }, "\u015Eu an \xE7evrimi\xE7i kimse yok.");
    const shown = rows.slice(0, CARD_LIMIT);
    const rest = Math.max(0, live.total - shown.length);
    return m("div", {
      className: "Framio-Online Framio-Online--card"
    }, m("div", {
      className: "Framio-Online-list"
    }, shown.map(r => {
      const a = r.activity;
      const line = activityText(a);
      return m(Link, {
        href: a && a.href ? a.href : app.route('user', {
          username: r.username
        }),
        className: 'Framio-Online-item' + (a && a.writing ? ' is-writing' : ''),
        title: `${r.displayName}: ${line}`,
        key: r.id
      }, m("span", {
        className: "Framio-Online-avatarWrap"
      }, this.avatar(r), m("span", {
        className: "Framio-Online-dot"
      })), m("span", {
        className: "Framio-Online-body"
      }, m("span", {
        className: "Framio-Online-name"
      }, r.displayName, r.isMe ? m("em", null, " (sen)") : null), m("span", {
        className: "Framio-Online-line"
      }, a ? m("i", {
        className: a.icon,
        "aria-hidden": "true"
      }) : null, m("span", null, line), a && a.writing ? m("span", {
        className: "Framio-Online-typing",
        "aria-hidden": "true"
      }, m("i", null), m("i", null), m("i", null)) : null)));
    })), m(Link, {
      href: onlinePageUrl(),
      className: "Framio-Online-all"
    }, m("span", null, rest ? `+${rest} kişi daha · ` : '', "T\xFCm\xFCn\xFC g\xF6r"), m("i", {
      className: "fas fa-arrow-right",
      "aria-hidden": "true"
    })));
  }

  /** Etkinliği görme izni olmayanlar: avatarlar */
  viewAvatars() {
    const users = (app.forum.onlineUsers() || []).filter(u => u !== undefined);
    const total = app.forum.totalOnlineUsers() || 0;
    if (onlineUsersState.isLoading && users.length === 0) return m(LoadingIndicator, null);
    if (!users.length) return m("div", {
      className: "Framio-Online-empty"
    }, "\u015Eu an \xE7evrimi\xE7i kimse yok.");
    return m("div", {
      className: "FoF-OnlineUsersWidget-users"
    }, m("div", {
      className: "FoF-OnlineUsersWidget-users-list"
    }, users.map(user => m(Link, {
      href: app.route('user', {
        username: user.slug()
      }),
      className: "FoF-OnlineUsersWidget-users-item"
    }, m(Tooltip, {
      text: user.displayName()
    }, m("span", {
      className: "Framio-Online-avatarWrap"
    }, m(Avatar, {
      user: user
    }), m("span", {
      className: "Framio-Online-dot"
    }))))), total > users.length ? m("span", {
      className: "FoF-OnlineUsersWidget-users-item FoF-OnlineUsersWidget-users-item--plus"
    }, m("span", {
      className: "Avatar"
    }, `+${total - users.length}`)) : null));
  }
}
flarum.reg.add('framio-widgets', 'online-users-widget/common/components/OnlineUsersWidget', OnlineUsersWidget);